SourceCode.Declaration:
/// <summary>
/// Per-worker, per-module allow/block for the four handheld warehouse workflows.
///
/// **Absence means allowed.** No row for a (user, module) pair is not "blocked" - it is "never
/// restricted", which is what every worker's account already means today, before this table
/// existed. A row only ever appears once an admin has explicitly touched that module for that
/// worker, in either direction - see HSMobileOpsUserService::appendModulePermissions and its own
/// note on why the app-side cache mirrors this exactly rather than defaulting to deny-all.
///
/// Modeled directly on HSMobileOpsUserWarehouse - a small per-user child table, one row per
/// thing being assigned - rather than a new mechanism.
/// </summary>
public class HSMobileOpsUserModulePermission extends common
{
}

Method.Source:
/// <summary>
/// Whether a worker may use a module, applying the absence-means-allowed rule: no row for
/// this (user, module) pair returns true, exactly like a worker an admin has never touched.
/// </summary>
public static boolean isAllowed(RefRecId _userRecId, HSMobileOpsModule _module)
{
    HSMobileOpsUserModulePermission permission;

    select firstOnly IsAllowed from permission
        where permission.UserRecId == _userRecId
           && permission.Module    == _module;

    if (!permission.RecId)
    {
        return true;
    }

    return permission.IsAllowed == NoYes::Yes;
}
